import java.io.*;

public class Main {
    static BufferedInputStream bin = new BufferedInputStream(System.in, 1 << 16);
    static byte[] buf = new byte[1 << 16];
    static int idx = 0, len = 0;

    static int read() throws IOException {
        if (idx == len) {
            len = bin.read(buf, 0, buf.length);
            idx = 0;
            if (len <= 0) return -1;
        }
        return buf[idx++];
    }

    static int nextInt() throws IOException {
        int c = read();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = read();
        boolean neg = false;
        if (c == '-') { neg = true; c = read(); }
        int x = 0;
        while (c >= '0' && c <= '9') { x = x * 10 + (c - '0'); c = read(); }
        return neg ? -x : x;
    }

    public static void main(String[] args) throws IOException {
        int N = nextInt();
        int M = nextInt();
        int[] ea = new int[Math.max(0, N - 1)];
        int[] eb = new int[Math.max(0, N - 1)];
        for (int i = 0; i < N - 1; i++) { ea[i] = nextInt(); eb[i] = nextInt(); }
        int[] fa = new int[Math.max(0, M - 1)];
        int[] fb = new int[Math.max(0, M - 1)];
        for (int i = 0; i < M - 1; i++) { fa[i] = nextInt(); fb[i] = nextInt(); }
        int c1 = findCenter(N, ea, eb);
        int c2 = findCenter(M, fa, fb);
        OutputStream os = new BufferedOutputStream(System.out);
        os.write((c1 + " " + c2 + "\n").getBytes());
        os.flush();
    }

    // Encontra o centro da árvore removendo folhas nível a nível.
    // Ligar os centros das duas árvores minimiza o diâmetro do sistema integrado,
    // que passa a ser max(d1, d2, r1 + r2 + 1), com r = ceil(d/2) o raio de cada árvore.
    static int findCenter(int n, int[] ea, int[] eb) {
        int[] deg = new int[n + 1];
        for (int i = 0; i < n - 1; i++) { deg[ea[i]]++; deg[eb[i]]++; }
        int[] off = new int[n + 2];
        for (int v = 1; v <= n; v++) off[v + 1] = off[v] + deg[v];
        int[] pos = off.clone();
        int[] adj = new int[2 * (n - 1)];
        for (int i = 0; i < n - 1; i++) {
            adj[pos[ea[i]]++] = eb[i];
            adj[pos[eb[i]]++] = ea[i];
        }
        boolean[] removed = new boolean[n + 1];
        int[] queue = new int[n];
        int head = 0, tail = 0;
        for (int v = 1; v <= n; v++) if (deg[v] == 1) queue[tail++] = v;
        int remaining = n;
        while (remaining > 2) {
            int k = tail - head;
            if (k == 0) break;
            for (int i = 0; i < k; i++) {
                int u = queue[head++];
                removed[u] = true;
                remaining--;
                for (int e = off[u]; e < off[u + 1]; e++) {
                    int v = adj[e];
                    if (!removed[v] && --deg[v] == 1) queue[tail++] = v;
                }
            }
        }
        for (int v = 1; v <= n; v++) if (!removed[v]) return v;
        return 1;
    }
}
